import { defaultProps } from "./index.js";
//#region src/components/MTableFilterRow/utils.js
var getLocalizationData = (localization) => ({
	...defaultProps.localization,
	...localization
});
var getLocalizedFilterPlaceHolder = (columnDef, localization) => {
	return columnDef.filterPlaceholder || getLocalizationData(localization).filterPlaceHolder || "";
};
//#endregion
export { getLocalizationData, getLocalizedFilterPlaceHolder };
